INSERT INTO documentos (coleccion, id, datos, orde, editado_por) VALUES ('paxinas_libres', '2027', '{"titulo":"V Feira da Sostibilidade · SENDA 2030","descricion":"O punto de encontro de SENDA 2030: un curso de investigación, diálogo entre territorios e acción protagonizada polo alumnado, que se mostra en abril no IES Luís Seoane.","nai":"edicions","imaxe":"f-multitude-corredor","imaxeAlt":"Corredor do IES Luís Seoane cheo de xente durante a Feira da Sostibilidade","borrador":false,"edicion":{"numero":5,"ano":2027,"datas":"28, 29 e 30 de abril de 2027","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"proxima","lema":"Eco-Étika en acción","cifras":[],"fitos":["II Foro de Desenvolvemento Local","I Conferencia COOPEDUGAL","Microproxectos Eco-Étika. Pensa. Actúa.","Voces do Sur Global"]},"seccions":[{"id":"portada","tipo":"heroe","oculta":false,"fondo":"escuro","etiqueta":"V edición · 28, 29 e 30 de abril de 2027","titulo":"V Feira da Sostibilidade","destaque":"SENDA 2030","texto":"IES Luís Seoane · Monte Porreiro, Pontevedra","imaxe":"f-multitude-corredor","imaxeAlt":"Corredor do IES Luís Seoane cheo de xente durante a Feira da Sostibilidade","botons":[{"texto":"O camiño ata a Feira","url":"#senda-2030","estilo":"principal"},{"texto":"Participa na Feira","url":"/participa/","estilo":"secundario"}],"cifras":[]},{"id":"presentacion","tipo":"presentacion","oculta":false,"fondo":"branco","etiqueta":"A edición","lema":"Eco-Étika en acción","texto":"O punto de encontro de SENDA 2030: un curso de investigación, diálogo entre territorios e acción protagonizada polo alumnado, que se mostra en abril no IES Luís Seoane.","chips":["II Foro de Desenvolvemento Local","I Conferencia COOPEDUGAL","Microproxectos Eco-Étika. Pensa. Actúa.","Voces do Sur Global"],"cifras":[]},{"id":"sp8far","tipo":"cronoloxia","oculta":false,"fondo":"branco","etiqueta":"SENDA 2030 · O camiño ata a Feira","titulo":"Investigar, contrastar, actuar.","fitos":[{"data":"Outono 2026","titulo":"Arranque","texto":"Coordinación cos centros participantes e liña de base.","estado":"agora"},{"data":"Novembro 2026 – marzo 2027","titulo":"Formación, laboratorio e ciencia cidadá","texto":"Formación docente en EpDCG, laboratorio de propostas educativas, obradoiros de cidadanía global e microproxectos Eco-Étika nas aulas.","estado":"proximo"},{"data":"Primavera 2027","titulo":"Diálogo entre territorios","texto":"Encontros local-global con docentes de América Latina, Eco-Étika Conecta e a campaña «Dálle a volta».","estado":"proximo"},{"data":"28–30 abril 2027","titulo":"V Feira da Sostibilidade","texto":"Tres xornadas no IES Luís Seoane co II Foro de Desenvolvemento Local e a I Conferencia COOPEDUGAL.","estado":"proximo"},{"data":"Maio – setembro 2027","titulo":"SENDA Aberta","texto":"Sistematización, documental e guía «Así fixemos SENDA» para que outros centros poidan adaptar a experiencia.","estado":"proximo"}],"ancla":"senda-2030","texto":"SENDA 2030. Xeración Eco-Étika é o proxecto de CIDEL Galicia e a Universidade de Vigo, co IES Luís Seoane, que une ciencia cidadá, práctica docente e participación xuvenil durante todo o curso. Así é o camiño:"},{"id":"sqor4w","tipo":"tarxetas","oculta":false,"fondo":"claro","etiqueta":"Na Feira","titulo":"Que haberá na V Feira.","columnas":3,"items":[{"titulo":"Stands e microproxectos do alumnado","texto":"Os microproxectos Eco-Étika presentados e dinamizados polo alumnado e o profesorado dos centros participantes.","imaxe":"f-stand-alumnas","imaxeAlt":"Alumnas explicando o seu stand"},{"titulo":"Investigacións de ciencia cidadá no rural","texto":"Os centros rurais vinculados a Postgrowth S.A.:Rural comparten as súas investigacións sobre a transición ecolóxica xusta.","imaxe":"f-alumnado-presenta-investigacion","imaxeAlt":"Alumnado presentando unha investigación"},{"titulo":"II Foro de Desenvolvemento Local","texto":"O rural ante a transición ecolóxica xusta: mesas de deliberación entre alumnado, profesorado e actores do territorio.","imaxe":"f-charla-auditorio","imaxeAlt":"Charla no salón de actos"},{"titulo":"I Conferencia COOPEDUGAL","texto":"Dúas xornadas de relatorios, experiencias e o espazo «O Local dende o Sur», vinculadas á Feira.","imaxe":"f-exposicion-carteis","imaxeAlt":"Exposición de carteis no corredor"},{"titulo":"Obradoiros, charlas-foro, xogos e escape rooms","texto":"Propostas de centros, entidades sociais, ONGD, universidade e iniciativas do territorio.","imaxe":"f-xogo-inclusivo","imaxeAlt":"Crianzas xogando a un xogo inclusivo"}]},{"id":"bn8xitsd","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen o fai posible","titulo":"Organiza, impulsan e apoian.","texto":"SENDA 2030 está financiado pola Xunta de Galicia a través da Cooperación Galega.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Co apoio de","entidades":["cooperacion-galega","cfr-pontevedra"]}]},{"id":"0u9vggnk","tipo":"noticias","oculta":false,"fondo":"branco","etiqueta":"Actualidade","titulo":"Noticias do camiño.","edicion":"2027","numero":6},{"id":"tj3qh2og","tipo":"chamada","oculta":false,"fondo":"morado","titulo":"Queres participar nesta edición?","texto":"Centros educativos, entidades, empresas e medios: escríbenos e contámosche como.","botons":[{"texto":"Participa","url":"/participa/","estilo":"principal"}]}]}', 973, 'Migración') ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now'), editado_por = 'Migración';
INSERT INTO documentos (coleccion, id, datos, orde, editado_por) VALUES ('paxinas_libres', '2026', '{"titulo":"IV Feira da Sostibilidade","descricion":"A máis grande ata o momento. 30 entidades e 13 centros educativos de Galicia, España e Europa, co I Foro de Desenvolvemento Local integrado na Feira.","nai":"edicions","imaxe":"f-stand-artesania","imaxeAlt":"Alumnado nun stand de artesanía na IV Feira da Sostibilidade","borrador":false,"edicion":{"numero":4,"ano":2026,"datas":"28, 29 e 30 de abril de 2026","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","cifras":[{"valor":"1.127","etiqueta":"participantes directos estimados"},{"valor":"30","etiqueta":"entidades colaboradoras"},{"valor":"14","etiqueta":"centros educativos de Galicia, España, Romanía e Italia"},{"valor":"120+","etiqueta":"alumnos e alumnas presentando nos stands"},{"valor":"528","etiqueta":"alumnado activo en obradoiros e dinámicas"},{"valor":"6.870+","etiqueta":"impacto indirecto estimado"}],"fitos":["I Foro de Desenvolvemento Local","Estudo de ciencia cidadá sobre o consumo de alimentos","30 entidades"]},"seccions":[{"id":"portada","tipo":"heroe","oculta":false,"fondo":"escuro","etiqueta":"IV edición · 28, 29 e 30 de abril de 2026","titulo":"IV Feira da Sostibilidade","texto":"IES Luís Seoane · Monte Porreiro, Pontevedra","imaxe":"f-stand-artesania","imaxeAlt":"Alumnado nun stand de artesanía na IV Feira da Sostibilidade","botons":[],"cifras":[]},{"id":"presentacion","tipo":"presentacion","oculta":false,"fondo":"branco","etiqueta":"A edición","texto":"A máis grande ata o momento. 30 entidades e 13 centros educativos de Galicia, España e Europa, co I Foro de Desenvolvemento Local integrado na Feira.","chips":["I Foro de Desenvolvemento Local","Estudo de ciencia cidadá sobre o consumo de alimentos","30 entidades"],"cifras":[{"valor":"1.127","etiqueta":"participantes directos estimados"},{"valor":"30","etiqueta":"entidades colaboradoras"},{"valor":"14","etiqueta":"centros educativos de Galicia, España, Romanía e Italia"},{"valor":"120+","etiqueta":"alumnos e alumnas presentando nos stands"},{"valor":"528","etiqueta":"alumnado activo en obradoiros e dinámicas"},{"valor":"6.870+","etiqueta":"impacto indirecto estimado"}]},{"id":"sgdn6x","tipo":"texto","oculta":false,"fondo":"branco","etiqueta":"A edición","corpo":"<p>A cuarta edición consolidou a Feira como referente galego de educación transformadora. Participaron 30 entidades e 13 centros educativos de Galicia, doutras comunidades autónomas e de Europa.</p>\n<p>No marco da Feira celebrouse o I Foro de Desenvolvemento Local, onde o alumnado do IES Luís Seoane presentou o estudo de ciencia cidadá sobre o patrón de consumo de alimentos en Pontevedra, desenvolvido co Post-Growth Innovation Lab da Universidade de Vigo: 587 enquisas recollidas en 6 zonas do municipio e propostas de axenda local para reducir a pegada de carbono.</p>"},{"id":"shxxxp","tipo":"galeria","oculta":false,"fondo":"claro","etiqueta":"Galería","titulo":"Imaxes da edición.","imaxes":[{"imaxe":"f-stand-2","alt":"Stand número 2 da Feira con materiais do alumnado"},{"imaxe":"f-stand-alumnas","alt":"Alumnas explicando o seu stand a outras visitantes"},{"imaxe":"f-xogo-inclusivo","alt":"Nenas e nenos xogando a un xogo inclusivo no chan"},{"imaxe":"f-stand-4-ruleta","alt":"Stand con ruleta de xogo e voluntariado atendendo"},{"imaxe":"f-exposicion-carteis","alt":"Exposición de carteis no corredor"},{"imaxe":"f-stand-15","alt":"Posto 15 do alumnado con produtos de deseño propio"},{"imaxe":"f-obradoiro-mans","alt":"Mans traballando nun obradoiro"},{"imaxe":"f-charla-auditorio","alt":"Charla no salón de actos ante o alumnado"},{"imaxe":"f-exposicion-gravados","alt":"Panel cunha exposición de gravados en branco e negro"},{"imaxe":"f-stand-sociocultural","alt":"Stand de La Sociocultural con libros e carteis"},{"imaxe":"f-xogo-mesa","alt":"Xogo de mesa educativo creado polo alumnado"},{"imaxe":"f-alumnado-presenta-investigacion","alt":"Alumnado presentando os resultados da investigación cidadá"}]},{"id":"sisf8o","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen participa","titulo":"Centros e entidades.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Colaboran","entidades":["oxfam-intermon","adega","cogami","solidariedade-internacional","afectados-a57","ec4rural","cruz-vermella","feitoria-verde","galicia-ambiental","sig-comercio-xusto","casa-grande-de-xanceda","o-colmenar-de-sara","coxapo","aspanorcel","fundacion-balms","asociacion-boa-vida","aquelarre","ecoloxistas-en-accion","sembrando-bioxias","cfr-pontevedra"]}]},{"id":"sje4dq","tipo":"lista","oculta":false,"fondo":"verde","titulo":"Centros educativos","items":["IES Luís Seoane","EEI Fina Casalderrey","CEP Marcos da Portela","IES de Poio","IES Valle-Inclán","IES Val do Asma","IES do Barral","IES Plurilingüe Rafael Dieste","CIFP A Xunqueira","IES Alexandre Bóveda","IES Monte Miravete (Murcia)","IES Alfonso VIII (Cuenca)","Colegiul Economic Regele Mihai I (Romanía)","ITCT A. Fossati–M. Da Passano (Italia)"]},{"id":"skopzp","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Documentos","items":[{"titulo":"Memoria IV Edición (en breve)"}]},{"id":"slsyzp","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Na prensa","items":[{"titulo":"El IES Luís Seoane implica a más de 30 entidades y centros en la IV Feira da Sustentabilidade","detalle":"Diario de Pontevedra · 29/04/2026","url":"https://www.diariodepontevedra.es/articulo/pontevedra/ies-luis-seoane-implica-mas-30-entidades-centros-iv-feira-da-sustentabilidade/202604290500151445549.html"},{"titulo":"El IES Luís Seoane convierte Pontevedra en un referente de educación ambiental","detalle":"Pontevedra Viva · 30/04/2026","url":"https://www.pontevedraviva.com/es/general/ies-luis-seoane-pontevedra-referente-educacion-ambiental_516871_102.html"},{"titulo":"Feira da Sustentabilidade en Monte Porreiro, un «regalo divino» en tiempos de individualismo feroz","detalle":"Diario de Pontevedra · 01/05/2026","url":"https://www.diariodepontevedra.es/articulo/pontevedra/regalo-divino-tiempos-individualismo-feroz/202605011637381445935.html"},{"titulo":"El IES Luís Seoane clausura una exitosa Feira da Sustentabilidade (fotogalería)","detalle":"Diario de Pontevedra · 01/05/2026","url":"https://www.diariodepontevedra.es/album/pontevedra/ies-luis-seoane-clausura-exitosa-feira-da-sustentabilidade/202605011605381446039.html"}]},{"id":"sm5l37","tipo":"noticias","oculta":false,"fondo":"claro","etiqueta":"Actualidade","titulo":"Noticias desta edición.","edicion":"2026","numero":6}]}', 974, 'Migración') ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now'), editado_por = 'Migración';
INSERT INTO documentos (coleccion, id, datos, orde, editado_por) VALUES ('paxinas_libres', '2025', '{"titulo":"III Feira da Sostibilidade","descricion":"Expansión a 9 centros educativos de Galicia e 22 entidades colaboradoras. Comeza a liña de ciencia cidadá co Post-Growth Innovation Lab.","nai":"edicions","borrador":false,"edicion":{"numero":3,"ano":2025,"datas":"Abril de 2025","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","cifras":[{"valor":"9","etiqueta":"centros educativos de Galicia"},{"valor":"22","etiqueta":"entidades colaboradoras"}],"fitos":["Inicio da liña de ciencia cidadá","Grupo de traballo intercentros aprobado polo CFR"]},"seccions":[{"id":"portada","tipo":"heroe","oculta":false,"fondo":"escuro","etiqueta":"III edición · Abril de 2025","titulo":"III Feira da Sostibilidade","texto":"IES Luís Seoane · Monte Porreiro, Pontevedra","botons":[],"cifras":[]},{"id":"presentacion","tipo":"presentacion","oculta":false,"fondo":"branco","etiqueta":"A edición","texto":"Expansión a 9 centros educativos de Galicia e 22 entidades colaboradoras. Comeza a liña de ciencia cidadá co Post-Growth Innovation Lab.","chips":["Inicio da liña de ciencia cidadá","Grupo de traballo intercentros aprobado polo CFR"],"cifras":[{"valor":"9","etiqueta":"centros educativos de Galicia"},{"valor":"22","etiqueta":"entidades colaboradoras"}]},{"id":"sb8zne","tipo":"texto","oculta":false,"fondo":"branco","etiqueta":"A edición","corpo":"<p>A terceira edición converteu a Feira nunha rede galega de innovación educativa. Participaron 9 centros educativos de Galicia e 22 entidades colaboradoras, e o CFR de Pontevedra aprobou o primeiro grupo de traballo intercentros.</p>\n<p>Nesta edición comezou a liña de ciencia cidadá co Post-Growth Innovation Lab da Universidade de Vigo, que converte o alumnado en investigador dos retos do seu territorio.</p>"},{"id":"scmtft","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen participa","titulo":"Centros e entidades.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]}]},{"id":"sdx5p8","tipo":"lista","oculta":false,"fondo":"verde","titulo":"Centros educativos","items":["IES Luís Seoane e 8 centros educativos de Galicia"]},{"id":"se67t0","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Documentos","items":[{"titulo":"Memoria III Edición"}]},{"id":"sfm9jm","tipo":"noticias","oculta":false,"fondo":"claro","etiqueta":"Actualidade","titulo":"Noticias desta edición.","edicion":"2025","numero":6}]}', 975, 'Migración') ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now'), editado_por = 'Migración';
INSERT INTO documentos (coleccion, id, datos, orde, editado_por) VALUES ('paxinas_libres', '2024', '{"titulo":"II Feira da Sostibilidade","descricion":"Consolidación da rede. Incorpóranse a Universidade de Vigo, o IES de Poio e o IES Rafael Dieste, e hai stands do alumnado de varios centros.","nai":"edicions","borrador":false,"edicion":{"numero":2,"ano":2024,"datas":"Abril de 2024","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","cifras":[],"fitos":["Incorporación da Universidade de Vigo","Primeiros stands de varios centros","Debate público sobre consumismo e desinformación"]},"seccions":[{"id":"portada","tipo":"heroe","oculta":false,"fondo":"escuro","etiqueta":"II edición · Abril de 2024","titulo":"II Feira da Sostibilidade","texto":"IES Luís Seoane · Monte Porreiro, Pontevedra","botons":[],"cifras":[]},{"id":"presentacion","tipo":"presentacion","oculta":false,"fondo":"branco","etiqueta":"A edición","texto":"Consolidación da rede. Incorpóranse a Universidade de Vigo, o IES de Poio e o IES Rafael Dieste, e hai stands do alumnado de varios centros.","chips":["Incorporación da Universidade de Vigo","Primeiros stands de varios centros","Debate público sobre consumismo e desinformación"],"cifras":[]},{"id":"s6f5ay","tipo":"texto","oculta":false,"fondo":"branco","etiqueta":"A edición","corpo":"<p>A segunda edición consolidou a rede. Incorporáronse a Universidade de Vigo, o IES de Poio e o IES Rafael Dieste, e por primeira vez houbo stands do alumnado de varios centros e un debate público sobre consumismo e desinformación.</p>"},{"id":"s7mgpj","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen participa","titulo":"Centros e entidades.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]}]},{"id":"s8254v","tipo":"lista","oculta":false,"fondo":"verde","titulo":"Centros educativos","items":["IES Luís Seoane","IES de Poio","IES Rafael Dieste"]},{"id":"s9523p","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Documentos","items":[{"titulo":"Memoria II Edición"}]},{"id":"ubamkvnk","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Na prensa","items":[{"titulo":"Regresa a Feira da Sostibilidade coa participación de máis estudantes","detalle":"Pontevedra Viva","url":"https://pontevedraviva.com/xeral/103434/regresa-eco-etika-sostibilidade-debate-estudantes-2024/"}]},{"id":"sasuvb","tipo":"noticias","oculta":false,"fondo":"claro","etiqueta":"Actualidade","titulo":"Noticias desta edición.","edicion":"2024","numero":6}]}', 976, 'Migración') ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now'), editado_por = 'Migración';
INSERT INTO documentos (coleccion, id, datos, orde, editado_por) VALUES ('paxinas_libres', '2023', '{"titulo":"I Feira da Sostibilidade","descricion":"A edición pioneira. Impulsada polo colectivo Eco-Étika, uniu comunidade educativa, asociacións e comercio local arredor da sostibilidade.","nai":"edicions","borrador":false,"edicion":{"numero":1,"ano":2023,"datas":"Abril de 2023","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","cifras":[],"fitos":["Impulsada por Eco-Étika","Premio Galicons-net"]},"seccions":[{"id":"portada","tipo":"heroe","oculta":false,"fondo":"escuro","etiqueta":"I edición · Abril de 2023","titulo":"I Feira da Sostibilidade","texto":"IES Luís Seoane · Monte Porreiro, Pontevedra","botons":[],"cifras":[]},{"id":"presentacion","tipo":"presentacion","oculta":false,"fondo":"branco","etiqueta":"A edición","texto":"A edición pioneira. Impulsada polo colectivo Eco-Étika, uniu comunidade educativa, asociacións e comercio local arredor da sostibilidade.","chips":["Impulsada por Eco-Étika","Premio Galicons-net"],"cifras":[]},{"id":"s1pb3s","tipo":"texto","oculta":false,"fondo":"branco","etiqueta":"A edición","corpo":"<p>A primeira Feira da Sostibilidade naceu da iniciativa do colectivo Eco-Étika, formado por alumnado do IES Luís Seoane. Converteu o centro nun espazo pioneiro en Galicia que uniu comunidades educativas, asociacións e comercio local arredor da sostibilidade e o consumo responsable.</p>"},{"id":"s27xfd","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen participa","titulo":"Centros e entidades.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsa","entidades":["cidel-galicia"]}]},{"id":"s3xxqq","tipo":"lista","oculta":false,"fondo":"verde","titulo":"Centros educativos","items":["IES Luís Seoane"]},{"id":"s4nuu7","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Documentos","items":[{"titulo":"Memoria I Edición"}]},{"id":"s5ivhh","tipo":"noticias","oculta":false,"fond